import React from 'react';
import { findChildByType } from '@fiverr-private/ui_utils';
export const useFindElements = children => {
  const icon = findChildByType(children, 'TimelineIcon');
  const title = findChildByType(children, 'TimelineTitle');
  const description = findChildByType(children, 'TimelineDescription');
  return {
    icon,
    title,
    description
  };
};