// ── Sub-components ────────────────────────────────────────────────────────

function SellerBadge({ level }: { level: SellerLevel }) {
  if (level === 'level1') return <SellerLevelOneBadge showTooltip={false} />;
  if (level === 'level2') return <SellerLevelTwoBadge showTooltip={false} />;
  if (level === 'top-rated') return <TopRatedBadge showTooltip={false} />;
  if (level === 'vetted-pro') return <VettedProBadge showTooltip={false} />;
  return null;
}

function GigCard({ gig }: { gig: Gig }) {
  return (
    <Stack direction="column" gap="2" minWidth="0px">
      <div
        style={{
          position: 'relative',
          aspectRatio: '4 / 3',
          borderRadius: 8,
          overflow: 'hidden',
          backgroundColor: '#e4e5e7',
          backgroundImage: `url(${gig.image})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
        }}
      >
        <div style={{ position: 'absolute', top: 8, right: 8 }}>
          <IconButton
            aria-label="Add to favorites"
            variant="ghost"
            size="sm"
            style={{ backgroundColor: 'rgba(255,255,255,0.85)' }}
          >
            <HeartIcon size="sm" />
          </IconButton>
        </div>
        {gig.hasVideo && (
          <div
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: 44,
              height: 44,
              borderRadius: '50%',
              backgroundColor: 'rgba(255,255,255,0.9)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <PlaySolidIcon size="md" />
          </div>
        )}
      </div>

      <Stack direction="row" gap="2" alignItems="center">
        <Avatar username={gig.sellerName} size="xs">
          <AvatarImage src={gig.sellerAvatar} />
        </Avatar>
        <Text size="b_sm" fontWeight="semibold" color="bodyPrimary">
          {gig.sellerName}
        </Text>
        <Container flex="1" />
        <SellerBadge level={gig.sellerLevel} />
      </Stack>

      <Text
        size="b_sm"
        color="bodyPrimary"
        style={{
          display: '-webkit-box',
          WebkitLineClamp: 2,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          lineHeight: '20px',
          minHeight: 40,
        }}
      >
        {gig.title}
      </Text>

      <Rating score={gig.rating} reviews={gig.reviews} variant="compact" />

      <Text size="b_md" fontWeight="bold" color="bodyPrimary">
        From {gig.priceFrom}
      </Text>

      {gig.offersVideoConsultation && (
        <Stack direction="row" gap="1" alignItems="center">
          <VideoIcon size="sm" />
          <Text size="b_sm" color="bodySecondary">
            Offers video consultations
          </Text>
        </Stack>
      )}
    </Stack>
  );
}

function GigGrid({ gigs, columns }: { gigs: Gig[]; columns: number }) {
  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
        gap: 24,
      }}
    >
      {gigs.map((gig) => (
        <GigCard key={gig.id} gig={gig} />
      ))}
    </div>
  );
}

function ActionCard({
  eyebrow,
  title,
  description,
  icon,
}: {
  eyebrow: string;
  title: string;
  description: string;
  icon: React.ReactElement;
}) {
  return (
    <Card
      variant="shadow"
      padding="5"
      borderRadius="2xl"
      flex="1"
      minWidth="0px"
      cursor="pointer"
      backgroundColor="white"
    >
      <Stack direction="column" gap="2">
        <Text size="b_xs" color="bodySecondary" fontWeight="semibold" style={{ letterSpacing: '0.5px' }}>
          {eyebrow.toUpperCase()}
        </Text>
        <Stack direction="row" gap="3" alignItems="center">
          <Center backgroundColor="grey_200" borderRadius="md" flexShrink="0" style={{ width: 40, height: 40 }}>
            {icon}
          </Center>
          <Stack direction="column" gap="0.5" flex="1" minWidth="0px">
            <Text size="b_md" fontWeight="bold" color="bodyPrimary">
              {title}
            </Text>
            <Text size="b_sm" color="bodySecondary">
              {description}
            </Text>
          </Stack>
        </Stack>
      </Stack>
    </Card>
  );
}

function SectionHeader({ title, subtitle, showAll }: { title: string; subtitle?: string; showAll?: boolean }) {
  return (
    <Stack direction="row" justifyContent="spaceBetween" alignItems="flexEnd">
      <Stack direction="column" gap="1">
        <Heading as="h2" size="h_md" color="bodyPrimary">
          {title}
        </Heading>
        {subtitle && (
          <Text size="b_md" color="bodySecondary">
            {subtitle}
          </Text>
        )}
      </Stack>
      {showAll && (
        <Link href="#" style={{ textDecoration: 'none' }}>
          <Stack direction="row" gap="1" alignItems="center">
            <Text size="b_md" fontWeight="semibold" color="bodyPrimary">
              Show All
            </Text>
            <ChevronRightIcon size="sm" />
          </Stack>
        </Link>
      )}
    </Stack>
  );
}

