// All feature labels across all packages (union, preserving order)
const COMPARE_ROWS = [
  'Up to 3 pages', 'Responsive design', 'Contact form',
  'SEO optimisation', 'User authentication', 'Database integration',
];

function ComparePackagesSection() {
  const colWidth = `${100 / (PACKAGES.length + 1)}%`;

  const cellStyle: React.CSSProperties = {
    padding: '12px 16px',
    borderBottom: '1px solid #e4e5e7',
    verticalAlign: 'middle',
  };
  const headerCellStyle: React.CSSProperties = {
    ...cellStyle,
    backgroundColor: '#fafafa',
    fontWeight: 600,
  };

  return (
    <Stack direction="column" gap="4">
      <Heading as="h2" size="h_sm">Compare packages</Heading>
      <div style={{ border: '1px solid #e4e5e7', borderRadius: 12, overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed' }}>
          <colgroup>
            <col style={{ width: colWidth }} />
            {PACKAGES.map((p) => <col key={p.name} style={{ width: colWidth }} />)}
          </colgroup>
          <thead>
            <tr>
              <th style={{ ...headerCellStyle, textAlign: 'left' }}>
                <Text size="b_sm" color="bodySecondary">Package</Text>
              </th>
              {PACKAGES.map((pkg) => (
                <th key={pkg.name} style={{ ...headerCellStyle, textAlign: 'left' }}>
                  <Stack direction="column" gap="1">
                    <Text size="b_lg" fontWeight="bold">${pkg.price}</Text>
                    <Text size="b_md" fontWeight="bold">{pkg.name}</Text>
                    <Text size="b_sm" color="bodySecondary">{pkg.description}</Text>
                  </Stack>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {COMPARE_ROWS.map((feature, i) => (
              <tr key={feature} style={{ backgroundColor: i % 2 === 0 ? '#fff' : '#fafafa' }}>
                <td style={cellStyle}>
                  <Text size="b_sm" color="bodySecondary">{feature}</Text>
                </td>
                {PACKAGES.map((pkg) => {
                  const f = pkg.features.find((f) => f.text === feature);
                  return (
                    <td key={pkg.name} style={{ ...cellStyle, textAlign: 'center' }}>
                      {f?.included
                        ? <CheckIcon size="sm" color="grey_1200" />
                        : <span style={{ color: '#c5c6c9', fontSize: 18, lineHeight: 1 }}>—</span>}
                    </td>
                  );
                })}
              </tr>
            ))}
            {/* Revisions row */}
            <tr style={{ backgroundColor: COMPARE_ROWS.length % 2 === 0 ? '#fff' : '#fafafa' }}>
              <td style={cellStyle}><Text size="b_sm" color="bodySecondary">Revisions</Text></td>
              {PACKAGES.map((pkg) => (
                <td key={pkg.name} style={{ ...cellStyle, textAlign: 'center' }}>
                  <Text size="b_sm" fontWeight="bold">{pkg.revisions}</Text>
                </td>
              ))}
            </tr>
            {/* Delivery row */}
            <tr style={{ backgroundColor: (COMPARE_ROWS.length + 1) % 2 === 0 ? '#fff' : '#fafafa' }}>
              <td style={cellStyle}><Text size="b_sm" color="bodySecondary">Delivery Time</Text></td>
              {PACKAGES.map((pkg) => (
                <td key={pkg.name} style={{ ...cellStyle, textAlign: 'center' }}>
                  <Text size="b_sm" fontWeight="bold">{pkg.deliveryDays} days</Text>
                </td>
              ))}
            </tr>
            {/* Select row */}
            <tr>
              {PACKAGES.map((pkg, i) => (
                <td key={pkg.name} style={{ ...cellStyle, textAlign: 'center' }} colSpan={i === 0 ? 2 : 1}>
                  {i === 0 && <td style={{ ...cellStyle, borderBottom: 'none' }} />}
                </td>
              ))}
            </tr>
            <tr style={{ borderTop: '1px solid #e4e5e7' }}>
              <td style={{ padding: '16px', borderBottom: 'none' }} />
              {PACKAGES.map((pkg) => (
                <td key={pkg.name} style={{ padding: '16px', textAlign: 'center', borderBottom: 'none' }}>
                  <Stack direction="column" gap="2" alignItems="center">
                    <Text size="b_sm" fontWeight="bold">${pkg.price}</Text>
                    <Button size="md" fullWidth>Select</Button>
                  </Stack>
                </td>
              ))}
            </tr>
          </tbody>
        </table>
      </div>
    </Stack>
  );
}

